-- Stravifx Learn: paid waitlist.
-- One row per checkout attempt. A row is created as 'pending' before the visitor is
-- sent to Paystack and moves to 'paid' only after the server has verified the
-- transaction with Paystack.
--
-- Safe to run more than once.

create table if not exists public.learn_waitlist (
  id bigint generated always as identity primary key,
  -- Paystack transaction reference, generated by the site (learn_<uuid>)
  reference text not null unique,
  email text not null check (email = lower(email)),
  full_name text not null,
  -- Amount in the currency's smallest unit, as Paystack expects (KES 2,500 = 250000)
  amount_minor integer not null check (amount_minor > 0),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  status text not null default 'pending' check (status in ('pending', 'paid', 'failed')),
  paid_at timestamptz,
  paystack_id bigint,
  channel text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.learn_waitlist is
  'Stravifx Learn paid waitlist. Written only by the site''s server; never exposed to browsers.';

-- "Is this email already on the waitlist?" and the paid-members export
create index if not exists learn_waitlist_email_idx on public.learn_waitlist (email);
create index if not exists learn_waitlist_paid_idx
  on public.learn_waitlist (paid_at desc)
  where status = 'paid';

-- Lock the table down. Row level security is on with no policies, so the
-- publishable (anon) key and signed-in users can read and write nothing.
-- The site's server uses the secret key, which bypasses RLS.
alter table public.learn_waitlist enable row level security;

revoke all on table public.learn_waitlist from anon, authenticated;
